import React, { useEffect, useState } from 'react';
import { View, Text, StyleSheet, FlatList, TextInput, Button, Alert } from 'react-native';
import { fetchWithAuth } from '../lib/api';

export default function ReviewScreen({ navigation, route }) {
  const { targetType, targetId, targetName } = route.params || {};
  const [reviews, setReviews] = useState([]);
  const [rating, setRating] = useState('5');
  const [comment, setComment] = useState('');
  const [unauthorized, setUnauthorized] = useState(false);

  useEffect(() => {
    fetchReviews();
  }, []);

  const fetchReviews = async () => {
    try {
      const response = await fetchWithAuth(`/api/reviews?targetType=${targetType}&targetId=${targetId}`);
      const data = await response.json();
      setReviews(data);
      setUnauthorized(false);
    } catch (error) {
      setUnauthorized(false);
      setReviews([]);
    }
  };

  const submitReview = async () => {
    if (!rating) return Alert.alert('Valitse arvosana');

    try {
      const response = await fetchWithAuth('/api/reviews', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ targetType, targetId, rating: Number(rating), comment })
      });

      if (response.status === 401) {
        setUnauthorized(true);
        return;
      }

      const result = await response.json();
      setComment('');
      setRating('5');
      fetchReviews();
      Alert.alert('Arvostelu lähetetty', `Kiitos arvostelusta ${result.reviewer}!`);
    } catch (error) {
      if (error.message === 'Unauthorized') {
        setUnauthorized(true);
      } else {
        Alert.alert('Arvostelu epäonnistui');
      }
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Arvostelut kohteelle:</Text>
      <Text style={styles.subtitle}>{targetName}</Text>
      <FlatList
        data={reviews}
        keyExtractor={(item) => item.id}
        ListEmptyComponent={<Text>Ei arvosteluja vielä.</Text>}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <Text style={styles.reviewer}>{item.reviewer}</Text>
            <Text style={styles.rating}>Arvio: {item.rating}/5</Text>
            <Text>{item.comment}</Text>
          </View>
        )}
      />
      <View style={styles.form}>
        <Text style={styles.section}>Jätä oma arvostelu</Text>
        <TextInput
          style={styles.input}
          placeholder="Arvostelusi"
          value={comment}
          onChangeText={setComment}
          multiline
        />
        <TextInput
          style={styles.input}
          placeholder="Arvosana 1-5"
          value={rating}
          onChangeText={setRating}
          keyboardType="numeric"
        />
        {unauthorized && (
          <Text style={styles.error}>Sinun täytyy kirjautua ensin.</Text>
        )}
        <Button title="Lähetä arvostelu" onPress={submitReview} />
        {unauthorized && (
          <Button title="Kirjaudu" onPress={() => navigation.navigate('Auth')} />
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 },
  title: { fontSize: 20, fontWeight: '700', marginBottom: 4 },
  subtitle: { fontSize: 16, marginBottom: 12, color: '#333' },
  card: { padding: 12, borderWidth: 1, borderColor: '#eee', borderRadius: 8, marginBottom: 12 },
  reviewer: { fontWeight: '700', marginBottom: 4 },
  rating: { marginBottom: 6 },
  form: { marginTop: 16 },
  section: { fontSize: 16, fontWeight: '700', marginBottom: 8 },
  input: { borderWidth: 1, borderColor: '#ccc', padding: 10, borderRadius: 6, marginBottom: 12, minHeight: 44 },
  error: { color: '#c00', marginBottom: 12 }
});
